/** @returns {Map<string, object>} */
export function buildTranslationLookup() {
  const map = new Map();
  for (const row of MAP_LABEL_TRANSLATIONS) {
    if (!row || !row.originalName || !row.nameKo) continue;
    map.set(row.originalName, row);
    const alt = row.originalName.replace(/・/g, '');
    if (alt !== row.originalName && !map.has(alt)) map.set(alt, row);
  }
  return map;
}

/**
 * MapLibre expression: name:ko → dictionary(name/name:en) → name:en → name
 */
export function translationPrimaryExpression(lookup = buildTranslationLookup()) {
  const pairs = [];
  for (const [original, row] of lookup) {
    pairs.push(original, row.nameKo);
  }
  const fallback = ['coalesce', ['get', 'name:en'], ['get', 'name']];
  if (pairs.length === 0) {
    return ['coalesce', ['get', 'name:ko'], ...fallback.slice(1)];
  }
  return [
    'coalesce',
    ['get', 'name:ko'],
    [
      'match',
      ['coalesce', ['get', 'name'], ''],
      ...pairs,
      [
        'match',
        ['coalesce', ['get', 'name:en'], ''],
        ...pairs,
        fallback,
      ],
    ],
  ];
}

export function japaneseNameExpression() {
  return ['coalesce', ['get', 'name:ja'], ['get', 'name'], ['get', 'name:en']];
}
